package org.commcare.personalId

import android.content.Context
import android.content.res.XmlResourceParser
import android.os.Bundle
import androidx.annotation.IdRes
import androidx.annotation.NavigationRes
import androidx.annotation.StringRes
import androidx.test.espresso.Espresso.onView
import androidx.test.espresso.assertion.ViewAssertions.matches
import androidx.test.espresso.matcher.ViewMatchers.isDescendantOfA
import androidx.test.espresso.matcher.ViewMatchers.isDisplayed
import androidx.test.espresso.matcher.ViewMatchers.withId
import androidx.test.espresso.matcher.ViewMatchers.withText
import org.commcare.dalvik.R
import org.hamcrest.Matchers.allOf
import org.xmlpull.v1.XmlPullParser

/**
 * A nav destination together with the arguments it is opened with and the toolbar title it must show.
 */
data class TitledScreen(
    @IdRes val destinationId: Int,
    @StringRes val titleRes: Int,
    val args: Bundle? = null,
)

/**
 * An `<action>` declared on a `<fragment>` destination of a nav graph.
 */
data class NavAction(
    @IdRes val sourceId: Int,
    @IdRes val actionId: Int,
    @IdRes val destinationId: Int,
)

object NavGraphTitleTestSupport {
    private const val ANDROID_NS = "http://schemas.android.com/apk/res/android"
    private const val APP_NS = "http://schemas.android.com/apk/res-auto"

    fun assertToolbarTitle(
        @StringRes titleRes: Int,
    ) {
        onView(allOf(withText(titleRes), isDescendantOfA(withId(R.id.toolbar))))
            .check(matches(isDisplayed()))
    }

    /**
     * Returns the actions that move from one fragment destination to a different fragment destination,
     * i.e. every forward navigation that a Back press can return from.
     */
    fun fragmentToFragmentActions(
        context: Context,
        @NavigationRes graphRes: Int,
    ): Set<NavAction> {
        val actions = mutableListOf<NavAction>()
        val dialogIds = mutableSetOf<Int>()
        var sourceId: Int? = null
        context.resources.getXml(graphRes).use { parser ->
            while (parser.next() != XmlPullParser.END_DOCUMENT) {
                if (parser.eventType != XmlPullParser.START_TAG) continue
                when (parser.name) {
                    "fragment" -> {
                        sourceId = parser.idAttribute()
                    }

                    "dialog" -> {
                        sourceId = null
                        dialogIds += parser.idAttribute()
                    }

                    "action" -> {
                        sourceId?.let {
                            actions +=
                                NavAction(
                                    sourceId = it,
                                    actionId = parser.idAttribute(),
                                    destinationId = parser.getAttributeResourceValue(APP_NS, "destination", 0),
                                )
                        }
                    }
                }
            }
        }
        return actions
            .filter { it.destinationId != it.sourceId && it.destinationId !in dialogIds }
            .toSet()
    }

    fun describe(
        context: Context,
        @IdRes id: Int,
    ): String = context.resources.getResourceEntryName(id)

    private fun XmlResourceParser.idAttribute(): Int = getAttributeResourceValue(ANDROID_NS, "id", 0)
}

package org.commcare.fragments.personalId

import android.os.Bundle
import androidx.navigation.fragment.DialogFragmentNavigator
import androidx.test.espresso.Espresso.pressBackUnconditionally
import androidx.test.ext.junit.runners.AndroidJUnit4
import org.commcare.CommCareTestApplication
import org.commcare.android.database.connect.models.PersonalIdSessionData
import org.commcare.dalvik.R
import org.commcare.personalId.NavGraphTitleTestSupport.assertToolbarTitle
import org.commcare.personalId.NavGraphTitleTestSupport.describe
import org.commcare.personalId.NavGraphTitleTestSupport.fragmentToFragmentActions
import org.commcare.personalId.TitledScreen
import org.commcare.utils.MockAndroidKeyStoreProvider
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Before
import org.junit.Rule
import org.junit.Test
import org.junit.rules.ErrorCollector
import org.junit.runner.RunWith
import org.robolectric.annotation.Config
import org.robolectric.shadows.ShadowLooper

/**
 * Checks the toolbar title of every fragment in nav_graph_personalid, both on arrival and after
 * pressing Back from each screen it navigates to.
 */
@Config(application = CommCareTestApplication::class)
@RunWith(AndroidJUnit4::class)
class PersonalIdActivityToolbarTitleTest : BasePersonalIdConfigurationTest<BasePersonalIdFragment>() {
    @get:Rule
    val errors = ErrorCollector()

    private var activityBooted = false

    @Before
    override fun setUp() {
        MockAndroidKeyStoreProvider.registerProvider()
        super.setUp()
    }

    @After
    override fun tearDown() {
        destroyActivity()
        super.tearDown()
        MockAndroidKeyStoreProvider.deregisterProvider()
    }

    @Test
    fun `every fragment destination has an expected title`() {
        launch()
        val fragmentIds =
            navHostFragment.navController.graph
                .filterNot { it is DialogFragmentNavigator.Destination }
                .map { it.id }
                .toSet()
        assertEquals(fragmentIds.map { describe(activity, it) }.toSet(), SCREENS.keys.map { describe(activity, it) }.toSet())
    }

    @Test
    fun `each fragment shows its title on arrival`() {
        SCREENS.values.forEach { screen ->
            check(describe(activity(), screen.destinationId)) {
                launch()
                open(screen)
                assertToolbarTitle(screen.titleRes)
            }
        }
    }

    @Test
    fun `pressing back from each forward navigation restores the visible screen's title`() {
        launch()
        val actions = fragmentToFragmentActions(activity, R.navigation.nav_graph_personalid)
        actions.forEach { action ->
            val source = SCREENS.getValue(action.sourceId)
            val target = SCREENS.getValue(action.destinationId)
            val case = "${describe(activity, source.destinationId)} -> ${describe(activity, target.destinationId)}"
            check(case) {
                launch()
                val opened = mutableListOf(SCREENS.getValue(R.id.personalid_phone_fragment))
                if (source.destinationId != R.id.personalid_phone_fragment) {
                    open(source)
                    opened += source
                }
                activity.runOnUiThread { navHostFragment.navController.navigate(action.actionId, target.args) }
                ShadowLooper.idleMainLooper()
                opened += target
                assertToolbarTitle(target.titleRes)

                pressBackUnconditionally()
                ShadowLooper.idleMainLooper()

                if (!activity.isFinishing) {
                    val currentId = navHostFragment.navController.currentDestination!!.id
                    assertToolbarTitle(opened.last { it.destinationId == currentId }.titleRes)
                }
            }
        }
    }

    private fun activity() = if (activityBooted) activity else launch().let { activity }

    private fun launch() {
        destroyActivity()
        bootActivityAndSeedSession(buildSessionData())
        activityController.visible()
        ShadowLooper.idleMainLooper()
        activityBooted = true
    }

    private fun destroyActivity() {
        if (activityBooted) {
            activityController.pause().stop().destroy()
            activityBooted = false
        }
    }

    private fun open(screen: TitledScreen) {
        activity.runOnUiThread { navHostFragment.navController.navigate(screen.destinationId, screen.args) }
        ShadowLooper.idleMainLooper()
    }

    private fun check(
        case: String,
        block: () -> Unit,
    ) {
        try {
            block()
        } catch (t: Throwable) {
            errors.addError(AssertionError(case, t))
        }
    }

    private fun buildSessionData() =
        PersonalIdSessionData(
            requiredLock = PersonalIdSessionData.PIN,
            token = "test_session_token",
            accountExists = true,
            userName = "Test User",
            phoneNumber = "+11234567890",
            maskedEmail = "u***@example.com",
        )

    companion object {
        private const val EMAIL = "user@example.com"

        private val SCREENS: Map<Int, TitledScreen> =
            listOf(
                TitledScreen(R.id.personalid_phone_fragment, R.string.connect_registration_title),
                TitledScreen(R.id.personalid_biometric_config, R.string.connect_appbar_title_app_lock),
                TitledScreen(R.id.personalid_otp_page, R.string.connect_verify_phone_title),
                TitledScreen(R.id.personalid_backup_code, R.string.connect_backup_code_title_confirm),
                TitledScreen(R.id.personalid_name, R.string.personalid_name_appbar_title),
                TitledScreen(R.id.personalid_photo_capture, R.string.personalid_capture_photo),
                TitledScreen(
                    R.id.personalid_email,
                    R.string.personalid_email_appbar_title,
                    Bundle().apply { putSerializable("workflow", EmailWorkFlow.RECOVERY) },
                ),
                TitledScreen(
                    R.id.personalid_send_email_otp_fragment,
                    R.string.personalid_send_email_otp_title,
                    Bundle().apply {
                        putString("email", EMAIL)
                        putSerializable("workflow", EmailWorkFlow.FORGOT_BACKUP_CODE_RECOVERY)
                    },
                ),
                TitledScreen(
                    R.id.personalid_email_verification,
                    R.string.personalid_email_verification_appbar_title,
                    Bundle().apply {
                        putString("email", EMAIL)
                        putSerializable("workflow", EmailWorkFlow.FORGOT_BACKUP_CODE_RECOVERY)
                        putInt("emailOtpRequestCount", 1)
                    },
                ),
                TitledScreen(
                    R.id.personalid_account_config_set_new_backup_code_fragment,
                    R.string.personalid_set_new_backup_code_title,
                ),
            ).associateBy { it.destinationId }
    }
}

