        if (mProviders.isEmpty()) {
            mListener?.onLocationRequestFailure(CommCareLocationListener.Failure.NoProvider)
            return
        }
        startLocationRequest()
    }

    private fun startLocationRequest() {
        if (mLocationRequestStarted) {
            // We've already started location request so no need to request again!
            return
        }
        mLocationRequestStarted = true
        mListener?.onLocationRequestStart()
        for (provider in mProviders) {
            mLocationManager.requestLocationUpdates(provider, 0L, 0.0f, mLocationListener)
        }
    }

    @SuppressLint("MissingPermission")
    override suspend fun getCurrentLocation(): Location? {
        if (!isLocationPermissionGranted(mContext)) return null
                    ConnectConstants.PERSONALID_LOCATION_PERMISSION_FAILURE,
                    buttonText
            );
        }
    }

    @Override
    public void missingPermissions() {
        if (!shouldShowPermissionRationale(requireActivity(), REQUIRED_PERMISSIONS)) {
            locationPermissionLauncher.launch(REQUIRED_PERMISSIONS);
        }
    }

    @Override
    public void onLocationServiceChange(boolean locationServiceEnabled) {
        if (!locationServiceEnabled) {
            location = null;
            setLocationToolTip(location);
            updateContinueButtonState();
        }
    }
}

