import org.robolectric.android.controller.ActivityController
import org.robolectric.annotation.Config
import org.robolectric.shadows.ShadowLooper

/**
 * Checks the toolbar title of every fragment in nav_graph_personalid_profile, both on arrival and
 * after pressing Back from each screen it navigates to.
 */
@Config(
    application = CommCareTestApplication::class,
    sdk = [31],
    shadows = [ShadowPhoneAuthProvider::class],
)
@RunWith(AndroidJUnit4::class)
class PersonalIdProfileActivityToolbarTitleTest {
    @get:Rule
    val errors = ErrorCollector()

    private val context: Context = ApplicationProvider.getApplicationContext()
    private val mockApiServer = PersonalIdMockApiServer(PersonalIdMockApiServer.CallbackMode.MAIN_LOOPER)

    private lateinit var connectUserDatabaseUtilMock: MockedStatic<ConnectUserDatabaseUtil>
    private lateinit var firebaseAnalyticsUtilMock: MockedStatic<FirebaseAnalyticsUtil>
    private var activityController: ActivityController<PersonalIdProfileActivity>? = null
    private lateinit var navController: NavController

    @Before
    fun setUp() {
        FirebaseTestUtils.initializeDefaultAppIfNeeded()
        ShadowPhoneAuthProvider.reset()
        connectUserDatabaseUtilMock = Mockito.mockStatic(ConnectUserDatabaseUtil::class.java)
        connectUserDatabaseUtilMock
            .`when`<ConnectUserRecord> { ConnectUserDatabaseUtil.getUser() }
            .thenReturn(
                ConnectUserRecord(
                    "+11234567890",
                    "test-user-id",
                    "test-password",
                    "Ada Lovelace",
                    "",
                    null,
                    null,
                    false,
                    "",
                    false,
                ).apply { email = EMAIL },
            )
        firebaseAnalyticsUtilMock = Mockito.mockStatic(FirebaseAnalyticsUtil::class.java)
        firebaseAnalyticsUtilMock
            .`when`<NavController.OnDestinationChangedListener> {
                FirebaseAnalyticsUtil.getNavControllerPageChangeLoggingListener()
            }.thenReturn(
                NavController.OnDestinationChangedListener { _: NavController, _: NavDestination, _: Bundle? -> },
            )
        mockApiServer.start()
    }

    @After
    fun tearDown() {
        destroyActivity()
        connectUserDatabaseUtilMock.close()
        firebaseAnalyticsUtilMock.close()
        mockApiServer.shutdown()
        ShadowPhoneAuthProvider.reset()
    }

    @Test
    fun `every fragment destination has an expected title`() {
        launch()
        val fragmentIds = navController.graph.map { it.id }.toSet()
        assertEquals(fragmentIds.map { describe(context, it) }.toSet(), SCREENS.keys.map { describe(context, it) }.toSet())
    }

    @Test
    fun `each fragment shows its title on arrival`() {
        (SCREENS.values + SEND_EMAIL_OTP_WORKFLOW_VARIANTS).forEach { screen ->
            check("${describe(context, screen.destinationId)} ${screen.args?.get("workflow") ?: ""}") {
                launch()
                open(screen)
                assertToolbarTitle(screen.titleRes)
            }
        }
    }

    @Test
    fun `pressing back from each forward navigation restores the visible screen's title`() {
        fragmentToFragmentActions(context, R.navigation.nav_graph_personalid_profile).forEach { action ->
            val source = SCREENS.getValue(action.sourceId)
            val target = SCREENS.getValue(action.destinationId)
            check("${describe(context, source.destinationId)} -> ${describe(context, target.destinationId)}") {
                launch()
                val opened = mutableListOf(SCREENS.getValue(R.id.personalid_profile_fragment))
                if (source.destinationId != R.id.personalid_profile_fragment) {
                    open(source)
                    opened += source
                }
                onUiThread { navController.navigate(action.actionId, target.args) }
                opened += target
                assertToolbarTitle(target.titleRes)

                pressBackUnconditionally()
                ShadowLooper.idleMainLooper()

                if (!activityController!!.get().isFinishing) {
                    val currentId = navController.currentDestination!!.id
                    val visible =
                        opened.lastOrNull { it.destinationId == currentId }
                            ?: throw AssertionError("Back landed on unexpected destination ${describe(context, currentId)}")
                    assertToolbarTitle(visible.titleRes)
                }
            }
        }
    }

    private fun launch() {
        destroyActivity()
        val controller = Robolectric.buildActivity(PersonalIdProfileActivity::class.java)
        activityController = controller
        controller
            .create()
            .postCreate(null)
            .start()
            .resume()
            .visible()
        ShadowLooper.idleMainLooper()
        navController =
            (controller.get().supportFragmentManager.findFragmentById(R.id.profile_nav_host) as NavHostFragment)
                .navController
    }

    private fun destroyActivity() {
        activityController?.let { if (!it.get().isDestroyed) it.pause().stop().destroy() }
        activityController = null
    }

    private fun open(screen: TitledScreen) = onUiThread { navController.navigate(screen.destinationId, screen.args) }

    private fun onUiThread(block: () -> Unit) {
        activityController!!.get().runOnUiThread { block() }
        ShadowLooper.idleMainLooper()
    }

    private fun check(
        case: String,
        block: () -> Unit,
    ) {
        try {
            block()
        } catch (t: Throwable) {
            errors.addError(AssertionError(case, t))
        }
    }

    companion object {
        private const val EMAIL = "ada@example.com"

        private fun sendEmailOtp(
            workflow: EmailWorkFlow,
            titleRes: Int,
        ) = TitledScreen(
            R.id.personalid_send_email_otp_fragment,
            titleRes,
            Bundle().apply {
                putString("email", EMAIL)
                putSerializable("workflow", workflow)
            },
        )

        private val SCREENS: Map<Int, TitledScreen> =
            listOf(
                TitledScreen(R.id.personalid_profile_fragment, R.string.personalid_profile_title),
                TitledScreen(R.id.personalid_profile_edit_fragment, R.string.personalid_profile_edit_title),
                TitledScreen(
                    R.id.personalid_email_verification_fragment,
                    R.string.personalid_email_verification_appbar_title,
                    Bundle().apply {
                        putString("email", EMAIL)
                        putSerializable("workflow", EmailWorkFlow.EXISTING_USER)
                        putInt("emailOtpRequestCount", 1)
                    },
                ),
                TitledScreen(
                    R.id.personalid_email_verification_forgot_backup_code_fragment,
                    R.string.personalid_email_verification_appbar_title,
                    Bundle().apply {
                        putString("email", EMAIL)
                        putInt("emailOtpRequestCount", 1)
                    },
                ),
                TitledScreen(
                    R.id.personalid_profile_backup_code_fragment,
                    R.string.connect_backup_code_title_confirm,
                    Bundle().apply { putSerializable("emailWorkflow", EmailWorkFlow.EXISTING_USER) },
                ),
                TitledScreen(
                    R.id.personalid_profile_send_phone_otp_fragment,
                    R.string.connect_verify_phone_title,
                    Bundle().apply { putString("pendingEmail", EMAIL) },
                ),
                TitledScreen(
                    R.id.personalid_profile_phone_verification_fragment,
                    R.string.connect_verify_phone_title,
                    Bundle().apply { putString("pendingEmail", EMAIL) },
                ),
                sendEmailOtp(EmailWorkFlow.FORGOT_BACKUP_CODE_EXISTING_USER, R.string.personalid_send_email_otp_title),
                TitledScreen(
                    R.id.personalid_profile_set_new_backup_code_fragment,
                    R.string.personalid_set_new_backup_code_title,
                ),
            ).associateBy { it.destinationId }

        private val SEND_EMAIL_OTP_WORKFLOW_VARIANTS =
            listOf(
                sendEmailOtp(EmailWorkFlow.PENDING_BACKUP_CODE, R.string.personalid_send_email_otp_pending_backup_code_title),
                sendEmailOtp(EmailWorkFlow.EXISTING_USER, R.string.personalid_email_verification_title),
            )
    }
}

